class EditorBottomButtonsView extends StatelessWidget {
  const EditorBottomButtonsView({super.key});

  @override
  Widget build(BuildContext context) {
    final bloc = context.read<IFlagEditorCubit>();
    return FCard(
      child: SizedBox(
        height: MediaQuery.of(context).size.height * 0.1,
        child: Row(
          spacing: 8,
          children: [
            Expanded(
              child: FButton(
                color: ThemePalette.greenButton,
                onPressed: () {
                  bloc.toggleStylesBoardOpen(true);
                },
                child: const AspectRatio(
                  aspectRatio: 1,
                  child: _BuildIcon(
                    title: 'Styles',
                    svg: _styles,
                  ),
                ),
              ),
            ),
            Expanded(
              child: FButton(
                color: ThemePalette.greenButton,
                onPressed: () {
                  bloc.toggleShapesBoardOpen(true);
                },
                child: const AspectRatio(
                  aspectRatio: 1,
                  child: _BuildIcon(
                    title: 'Shapes',
                    svg: _shapes,
                  ),
                ),
              ),
            ),
            Expanded(
              child: FButton(
                color: ThemePalette.greenButton,
                onPressed: () {
                  bloc.toggleEmblemsBoardOpen(true);
                },
                child: const AspectRatio(
                  aspectRatio: 1,
                  child: _BuildIcon(
                    title: 'Emblems',
                    svg: _emblems,
                  ),
                ),
              ),
            ),
            Expanded(
              child: ShopItemView(
                tag: 'editor.custom_paint',
                builder: (BuildContext context, bool isBought) {
                  return FButton(
                    onPressed: () {
                      bloc.toggleCustomPaintBoardOpen(true);
                    },
                    color: ThemePalette.orange,
                    child: const AspectRatio(
                      aspectRatio: 1,
                      child: _BuildIcon(
                        title: 'Custom',
                        svg: _custom,
                      ),
                    ),
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _BuildIcon extends StatelessWidget {
  final String title;
  final String svg;

  const _BuildIcon({
    super.key,
    required this.title,
    required this.svg,
  });

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (BuildContext context, BoxConstraints constraints) {
        return Stack(
          children: [
            Center(
              child: Transform.translate(
                offset: const Offset(0, -24),
                child: SizedBox(
                  width: constraints.maxWidth / 1.1,
                  child: SvgPicture.string(svg),
                ),
              ),
            ),
            Align(
              alignment: Alignment.bottomCenter,
              child: Padding(
                padding: const Pad(bottom: 6),
                child: FText(
                  title,
                  textAlign: TextAlign.center,
                  textStyle: const TextStyle(fontSize: 14),
                ),
              ),
            ),
          ],
        );
      },
    );
  }
}

